#!/usr/bin/env python3
"""Regenerate ground truth for CSX-003_Q2 expert error attribution."""

from __future__ import annotations

import csv
import html
import json
import math
import re
from datetime import date
from pathlib import Path
from typing import Any, Callable


TASK_ID = "CSX-003_Q2"
EVENT_ID = "CSX-003"
ANSWER_TYPE = "expert_error_attribution"
HUMID_HEAT_THRESHOLD_HOURS = 24


def package_dir() -> Path:
    return Path(__file__).resolve().parents[3] / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def manifest_rows(root: Path) -> list[dict[str, str]]:
    with (root / "metadata" / "files.csv").open("r", encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


def select_file(rows: list[dict[str, str]], category: str, rel_contains: str) -> str:
    valid_statuses = {"downloaded", "success", "remote_verified", "local_file_found"}
    matches = [
        row["relative_path"]
        for row in rows
        if row.get("data_category") == category
        and rel_contains in row.get("relative_path", "")
        and row.get("file_status") in valid_statuses
    ]
    if not matches:
        raise FileNotFoundError(f"no manifest file for {category} containing {rel_contains}")
    return sorted(matches)[0]


def parse_date(value: str) -> date:
    return date.fromisoformat(value)


def in_window(day: str, start: str, end: str) -> bool:
    parsed = parse_date(day)
    return parse_date(start) <= parsed <= parse_date(end)


def longest_run(rows: list[dict[str, Any]], predicate: Callable[[dict[str, Any]], bool]) -> dict[str, Any]:
    best: list[dict[str, Any]] = []
    current: list[dict[str, Any]] = []
    for row in rows:
        if predicate(row):
            current.append(row)
        else:
            if len(current) > len(best):
                best = current
            current = []
    if len(current) > len(best):
        best = current
    return {
        "days": len(best),
        "start": best[0]["date"] if best else None,
        "end": best[-1]["date"] if best else None,
    }


def stull_wet_bulb_c(temperature_c: float, relative_humidity: float) -> float:
    rh = max(1.0, min(100.0, float(relative_humidity)))
    t = float(temperature_c)
    return (
        t * math.atan(0.151977 * math.sqrt(rh + 8.313659))
        + math.atan(t + rh)
        - math.atan(rh - 1.676331)
        + 0.00391838 * rh**1.5 * math.atan(0.023101 * rh)
        - 4.686035
    )


def clean_html_text(raw: str) -> str:
    text = re.sub(r"<script.*?</script>", " ", raw, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip().lower()


def matched_water_terms(text: str) -> list[str]:
    candidates = [
        "poyang lake",
        "drought",
        "drained",
        "freshwater lake",
        "water levels",
        "irrigation",
        "shipping",
        "drinking water",
    ]
    return [term for term in candidates if term in text]


def rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "schema_and_classification",
                "points": 3,
                "description": "Returns the required expert_error_attribution JSON and corrected_classification compound_persistent_heat_with_water_stress.",
            },
            {
                "name": "source_paths",
                "points": 3,
                "description": "Uses package-relative paths for the locked anchor, Open-Meteo archive, NASA Poyang Lake report, and rejected alternatives.",
            },
            {
                "name": "event_window_and_record_counts",
                "points": 3,
                "description": "Uses the locked 2022-06-01 to 2022-08-31 event window and reports 92 daily records and 2208 hourly records from the heat archive.",
            },
            {
                "name": "heat_persistence_and_peak",
                "points": 4,
                "description": "Computes the 11-day compound heat run from 2022-08-12 to 2022-08-22 and the 44.0 C apparent-temperature peak on 2022-08-20.",
            },
            {
                "name": "humid_heat_error_attribution",
                "points": 3,
                "description": "Computes 1 wet-bulb hour at or above 30 C, max wet bulb 30.6 C at 2022-08-16T18:00, and the 23-hour shortfall against the 24-hour humid-heat-only threshold.",
            },
            {
                "name": "water_stress_context",
                "points": 2,
                "description": "Identifies the NASA Poyang Lake report as direct event context and includes package-derived water-stress terms without inventing unreported values.",
            },
            {
                "name": "insufficient_alternative_rejection",
                "points": 2,
                "description": "Rejects at least one tempting basis such as humid_heat_only or event_anchor_only with a numeric or source-path reason.",
            },
        ],
    }


def main() -> None:
    root = package_dir()
    rows = manifest_rows(root)

    anchor_rel = select_file(rows, "event_reports", "Locked_event_anchor_2022_China")
    openmeteo_rel = select_file(rows, "physical_hazard", "Open-Meteo_historical_archive")
    poyang_rel = select_file(rows, "event_reports", "Parched_Poyang_Lake")

    anchor = read_json(root / anchor_rel)
    openmeteo = read_json(root / openmeteo_rel)
    poyang_text = clean_html_text(read_text(root / poyang_rel))

    event_window = anchor["temporal_window"]
    start = event_window["start_date"]
    end = event_window["end_date"]

    daily = openmeteo["daily"]
    daily_rows = [
        {
            "date": day,
            "tmax": float(tmax),
            "tmin": float(tmin),
            "apparent_max": float(apparent),
        }
        for day, tmax, tmin, apparent in zip(
            daily["time"],
            daily["temperature_2m_max"],
            daily["temperature_2m_min"],
            daily["apparent_temperature_max"],
        )
        if in_window(day, start, end)
    ]

    hourly = openmeteo["hourly"]
    hourly_rows = [
        {
            "time": timestamp,
            "temperature_c": float(temp),
            "relative_humidity_pct": float(rh),
            "wet_bulb_c": stull_wet_bulb_c(float(temp), float(rh)),
        }
        for timestamp, temp, rh in zip(
            hourly["time"],
            hourly["temperature_2m"],
            hourly["relative_humidity_2m"],
        )
        if in_window(timestamp[:10], start, end)
    ]

    compound_run = longest_run(
        daily_rows,
        lambda row: row["tmax"] >= 35.0 and row["tmin"] >= 28.0 and row["apparent_max"] >= 40.0,
    )
    peak_apparent = max(daily_rows, key=lambda row: row["apparent_max"])
    max_wet_bulb = max(hourly_rows, key=lambda row: row["wet_bulb_c"])
    wet_bulb_ge_30_hours = sum(row["wet_bulb_c"] >= 30.0 for row in hourly_rows)
    peak_apparent_c = round(peak_apparent["apparent_max"], 1)
    max_wet_bulb_c = round(max_wet_bulb["wet_bulb_c"], 1)

    expected_response = {
        "answer_type": ANSWER_TYPE,
        "corrected_classification": "compound_persistent_heat_with_water_stress",
        "error_attribution": {
            "error_class": "wrong_operation_and_overdominant_index",
            "rejected_counterfactual": "humid_heat_only",
            "wrong_operation": "Treating any wet-bulb >=30 C hour as sufficient to dominate the event diagnosis.",
            "correct_operation": "Count wet-bulb >=30 C hours inside the locked window and compare that duration with persistent daily heat and water-stress evidence.",
        },
        "evidence_basis": {
            "event_window": {
                "path": anchor_rel,
                "start": start,
                "end": end,
                "daily_records": len(daily_rows),
                "hourly_records": len(hourly_rows),
            },
            "heat_source": {
                "path": openmeteo_rel,
                "compound_run_days": compound_run["days"],
                "compound_run_start": compound_run["start"],
                "compound_run_end": compound_run["end"],
                "peak_apparent_temp_c": peak_apparent_c,
                "peak_apparent_temp_date": peak_apparent["date"],
            },
            "humidity_check": {
                "path": openmeteo_rel,
                "wet_bulb_ge_30_hours": wet_bulb_ge_30_hours,
                "max_wet_bulb_c": max_wet_bulb_c,
                "max_wet_bulb_time": max_wet_bulb["time"],
                "humid_heat_duration_threshold_hours": HUMID_HEAT_THRESHOLD_HOURS,
            },
            "water_stress_report": {
                "path": poyang_rel,
                "role": "direct_event_context",
                "matched_terms": matched_water_terms(poyang_text),
            },
        },
        "calculation_check": {
            "compound_heat_rule": "Tmax >=35 C AND Tmin >=28 C AND apparent_temperature_max >=40 C",
            "wet_bulb_formula": "Stull approximation from hourly temperature_2m and relative_humidity_2m",
            "humid_heat_shortfall_hours": HUMID_HEAT_THRESHOLD_HOURS - wet_bulb_ge_30_hours,
            "apparent_minus_wet_bulb_peak_c": round(peak_apparent_c - max_wet_bulb_c, 1),
        },
        "insufficient_alternatives": [
            {
                "basis": "humid_heat_only",
                "paths": [openmeteo_rel],
                "reason_code": "insufficient_duration",
                "numeric_or_path_reason": "Only 1 hour has estimated wet-bulb >=30 C, 23 hours below the 24-hour duration threshold.",
            },
            {
                "basis": "event_anchor_only",
                "paths": [anchor_rel],
                "reason_code": "weak_context",
                "numeric_or_path_reason": "The anchor supplies the 2022-06-01 to 2022-08-31 window but not the daily heat, hourly wet-bulb, or Poyang Lake stress measurements.",
            },
        ],
        "minimal_required_paths": [anchor_rel, openmeteo_rel, poyang_rel],
        "final_assessment": "The humid-heat-only diagnosis is an operation error: one high wet-bulb hour is insufficient, while the package supports persistent compound heat with Poyang Lake water stress.",
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "expert_error_attribution",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "expert_error_attribution",
        "primary_gt": expected_response,
        "key_values": {
            "thresholds": {
                "compound_tmax_c_min": 35.0,
                "compound_tmin_c_min": 28.0,
                "compound_apparent_c_min": 40.0,
                "wet_bulb_c_min": 30.0,
                "humid_heat_duration_threshold_hours": HUMID_HEAT_THRESHOLD_HOURS,
            },
            "intermediate_values": {
                "daily_records_in_window": len(daily_rows),
                "hourly_records_in_window": len(hourly_rows),
                "compound_run": compound_run,
                "peak_apparent_temperature_c": peak_apparent_c,
                "peak_apparent_temperature_date": peak_apparent["date"],
                "wet_bulb_ge_30_hours": wet_bulb_ge_30_hours,
                "max_wet_bulb_c": max_wet_bulb_c,
                "max_wet_bulb_time": max_wet_bulb["time"],
                "humid_heat_shortfall_hours": HUMID_HEAT_THRESHOLD_HOURS - wet_bulb_ge_30_hours,
                "apparent_minus_wet_bulb_peak_c": round(peak_apparent_c - max_wet_bulb_c, 1),
            },
        },
        "rubric": rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": ["metadata/files.csv", anchor_rel, openmeteo_rel, poyang_rel],
            "event_window_source": anchor["temporal_window"].get("source"),
        },
    }

    (Path(__file__).resolve().parent / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
